import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.hw3Av5Vn.js";const m=JSON.parse('{"title":"Exporting","description":"","frontmatter":{},"headers":[],"relativePath":"EXPORTING.md","filePath":"EXPORTING.md"}'),n={name:"EXPORTING.md"};function r(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to &quot;Exporting&quot;">​</a></h1><p>Besides playing a song in real time, llamatron writes a song out: as a Live set to finish in a DAW, as MIDI files for any other DAW or player, or as a WAV file to listen to anywhere. This page covers every kind of export, where the files go, and exporting from the command line; <a href="./GETTING_STARTED#opening-and-saving">Opening and Saving</a> covers saving the set itself.</p><h2 id="tracker-export" tabindex="-1">Tracker Export <a class="header-anchor" href="#tracker-export" aria-label="Permalink to &quot;Tracker Export&quot;">​</a></h2><p><code>Ctrl+X</code>, on any page, exports the current song and asks which kind first. A set that hasn&#39;t been saved yet is saved first, since an export is named after the set&#39;s file and written beside it. When the export is written, the status line says where it went.</p><p>Every export is named <code>&lt;set&gt;_&lt;song&gt;</code>, so <code>songs/foo.yml</code> with a song called <code>bar</code> exports as:</p><table tabindex="0"><thead><tr><th>Kind</th><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td>Ableton Live set</td><td><code>songs/foo_bar.als</code></td><td>The main one: each track a MIDI track, its clips in Session View and the scenes laid end to end in Arrangement View, ready for instruments, effects and mixing.</td></tr><tr><td>MIDI (Stems)</td><td><code>songs/foo_bar_stem_001-lead.mid</code> and so on</td><td>A file per track, each the full length of the song with the tempo changes, for hardware and samplers that take one file at a time.</td></tr><tr><td>MIDI (Single File)</td><td><code>songs/foo_bar.mid</code></td><td>One file with a track per track and the tempo changes, which most DAWs import as aligned tracks in one drop.</td></tr><tr><td>MIDI (Clips)</td><td><code>songs/foo_bar_clip_s_002-chorus-t_001-lead.mid</code> and so on</td><td>A file per clip, named by scene and track, to drag into a project one by one.</td></tr><tr><td>MIDI (General MIDI)</td><td><code>songs/foo_bar_gm.mid</code></td><td>One file for any General MIDI player, GarageBand or a phone: drums on channel 10, every other track on a channel of its own, each with its instrument&#39;s GM sound.</td></tr><tr><td>WAV (FluidSynth)</td><td><code>songs/foo_bar.wav</code></td><td>The song as audio, for anyone with no DAW: the tracks whose instrument&#39;s Device is <code>*FluidSynth</code>, played by FluidSynth faster than real time and normalized to a peak 1 dB below full scale. Choosing it says first that only those tracks are in it, and it needs FluidSynth installed.</td></tr></tbody></table><h2 id="export-contents" tabindex="-1">Export Contents <a class="header-anchor" href="#export-contents" aria-label="Permalink to &quot;Export Contents&quot;">​</a></h2><p>An export plays the song as written, every scene once through from the top, as Live&#39;s Arrangement View lays it out, with every generator, groove, register and random choice played into the notes. A song with no seed exports a new take each time; set a seed on the Song page to export the same take every time.</p><p>Some things belong to real-time playback alone and no export reads them: instruments&#39; devices, a clip&#39;s follow action and a scene&#39;s Launch together, the Live response, and anything you did by hand while the song played. Muted tracks are left out of the MIDI and WAV exports, and in the Live set they are switched off. The MIDI files lay the scenes end to end as Live&#39;s Arrangement View does, so a track that plays nothing in the first scenes starts with silence and every file lines up. Every MIDI file carries the song&#39;s time signature, and so does the Live set, so a DAW draws its bar lines on the song&#39;s beats.</p><h2 id="file-locations" tabindex="-1">File Locations <a class="header-anchor" href="#file-locations" aria-label="Permalink to &quot;File Locations&quot;">​</a></h2><p>Exports sit beside the set&#39;s file, so a set and its exports stay together wherever you run llamatron from, and every file of a song starts with <code>&lt;set&gt;_&lt;song&gt;</code>, so exporting one song never touches another&#39;s.</p><p>Writing a Live set over an earlier one asks first, once in a session for each set, because replacing it loses anything you saved over that set in Live; to keep work you&#39;ve done in Live, save it there under another name. The MIDI kinds and the WAV just write over their earlier files. The exports of the sets in <code>examples/</code> are ignored by git.</p><p>In Live, each llamatron track is a MIDI track with no instrument, so drop one onto each track to hear it. Scenes keep their names, and each clip is named after the pattern it plays. The project was made with Ableton Live 12.3, and later versions should open it.</p><h2 id="command-line-export" tabindex="-1">Command-Line Export <a class="header-anchor" href="#command-line-export" aria-label="Permalink to &quot;Command-Line Export&quot;">​</a></h2><p><code>--to</code> exports a set without opening the tracker, writing every song in it beside the set&#39;s file, the same as <code>Ctrl+X</code>. On its own it writes Live sets, and it can name another kind: <code>ableton</code>, <code>midi</code> (MIDI (Single File)), <code>stems</code>, <code>cliptree</code> (MIDI (Clips)), <code>gm</code> (MIDI (General MIDI)) or <code>wav</code> (WAV (FluidSynth)). Put it after the set&#39;s name:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>llamatron examples/by_genre/electronic/minimal_techno.yml --to</span></span>
<span class="line"><span>llamatron examples/by_genre/electronic/minimal_techno.yml --to midi</span></span>
<span class="line"><span>llamatron examples/by_genre/electronic/minimal_techno.yml --to wav --out exports</span></span>
<span class="line"><span>llamatron examples/by_genre/electronic/minimal_techno.yml --to ableton --replace</span></span>
<span class="line"><span>llamatron examples/learning/04_scale.yml --to --song &quot;Scale demo&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--song</code></td><td>Exports only the song with that name.</td></tr><tr><td><code>--out</code></td><td>Writes into that folder, with the same file names, in place of the set&#39;s own folder.</td></tr><tr><td><code>--replace</code></td><td>Removes each song&#39;s earlier export first, so you can export again and listen.</td></tr><tr><td><code>--template</code></td><td>Builds the Live set from another Live set.</td></tr><tr><td><code>--seed</code></td><td>Exports with that seed in place of the song&#39;s, so an export can be repeated exactly.</td></tr><tr><td><code>--force</code></td><td>Exports a set file that holds values llamatron can&#39;t use, each changed the way the tracker&#39;s dialog would change it, listing what it changed. Without it such a file isn&#39;t exported. The file itself is never changed.</td></tr></tbody></table><p>These only work with <code>--to</code>.</p><h2 id="batch-export-scripts" tabindex="-1">Batch Export Scripts <a class="header-anchor" href="#batch-export-scripts" aria-label="Permalink to &quot;Batch Export Scripts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>What it does</th></tr></thead><tbody><tr><td><code>sh user_scripts/demos_to_live_sets.sh</code></td><td>Every example as a Live set beside it, replacing earlier exports.</td></tr><tr><td><code>sh user_scripts/demos_to_midi.sh</code></td><td>Every example as one General MIDI file in <code>previews/</code>, for any MIDI player.</td></tr><tr><td><code>sh user_scripts/demos_to_wavs.sh</code></td><td>Those previews as WAV files through FluidSynth, installing it the first time.</td></tr><tr><td><code>sh user_scripts/play_demo.sh</code></td><td>Pick one of those WAV files from a list and hear it.</td></tr></tbody></table>`,20)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
